(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1 = Math.sin(x*0.018+t*0.3)*12 + Math.cos(y*0.022-t*0.25)*8;
  const warp2 = Math.cos(x*0.015-t*0.2)*10 + Math.sin(y*0.02+t*0.35)*14;
  const warp3 = Math.sin((x+y)*0.01+t*0.15)*6 + Math.cos((x-y)*0.012-t*0.18)*5;
  const sx = x + warp1 + warp3, sy = y + warp2 + warp3;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.2, 1.0],
    [340+Math.cos(t*0.45)*95, 155+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*130, 110+Math.cos(t*0.42+1)*80, 0.055, 2.5, 1.1],
    [90+Math.cos(t*0.7+1)*75, 190+Math.sin(t*0.55+3)*55, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*85, 55+Math.cos(t*0.8+2)*65, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.32+5)*110, 210+Math.sin(t*0.48)*70, 0.085, 2.0, 0.95],
    [280+Math.sin(t*0.62+3)*70, 30+Math.cos(t*0.52+4)*40, 0.1, 1.4, 0.8],
    [60+Math.cos(t*0.44+2)*90, 120+Math.sin(t*0.38+5)*60, 0.07, 2.3, 1.0]
  ];
  let aS = 0, iS = 0, aS2 = 0, iS2 = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const d2 = Math.sqrt((sx-sY)**2 + (sy-sX)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.8) * w;
    aS2 += Math.sin(d2*f*1.3 - t*sp*0.8 + 0.5) * w * 0.4;
    iS2 += Math.cos(d2*f*0.9 + t*sp*0.4 - 2.0) * w * 0.4;
  }
  const n = 8;
  const act = (aS+aS2)/n, inh = (iS+iS2)/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.028+t*0.7) + Math.sin(sx*0.025-sy*0.038+t*1.0))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.25 + Math.sin((sx-sy)*0.085-t*1.8)*0.25;
  const bg3 = Math.sin(sx*0.06+t*0.5)*Math.cos(sy*0.055-t*0.4)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3 = Math.sin(dist*0.08-ang*2-t*2.5)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const voronoi = (() => {
    let md = 99;
    for (let i = 0; i < src.length; i++) {
      const vx = src[i][0] + Math.sin(t*0.3+i*1.7)*20;
      const vy = src[i][1] + Math.cos(t*0.25+i*2.1)*20;
      const d = Math.sqrt((sx-vx)**2 + (sy-vy)**2);
      if (d < md) md = d;
    }
    return Math.sin(md*0.15-t*0.8)*0.2;
  })();
  const feed = act*0.8 + bg*0.25 + spiral*0.3 + voronoi;
  const kill = inh*0.7 + Math.abs(act)*0.15;
  const reaction = Math.tanh((feed - kill)*2.0);
  const laplacian = (() => {
    const s = (dx, dy) => {
      const nx = sx+dx, ny = sy+dy;
      let la = 0, li = 0;
      for (const [sX, sY, f, sp, w] of src) {
        const d = Math.sqrt((nx-sX)**2 + (ny-sY)**2);
        la += Math.sin(d*f - t*sp)*w;
        li += Math.sin(d*f*0.65 + t*sp*0.55 + 1.8)*w;
      }
      return Math.tanh((la/n - li*0.7/n)*2.0);
    };
    const c = reaction;
    return (s(3,0)+s(-3,0)+s(0,3)+s(0,-3)-4*c)*0.25;
  })();
  const rd = Math.tanh(reaction + laplacian*1.8);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t)*0.5)*1.5)*0.2;
  const micro = Math.sin(sx*0.3+sy*0.2+t*3)*Math.cos(sx*0.2-sy*0.3-t*2.5)*0.08;
  const blend = rd*0.6 + cell*0.15 + micro + spiral*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,45,88],[18,85,120],[30,130,135],[120,170,100],
    [210,195,65],[230,140,60],[210,85,75],[160,50,85],[90,25,70],[40,15,55],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx - i;
  const c0 = pal[i], c1 = pal[i+1];
  const pulse = 0.85 + Math.sin(rd*Math.PI*1.5)*0.15;
  const edge = Math.abs(rd)>0.65 ? 1.2 : (Math.abs(rd)>0.4 ? 1.05 : 0.95);
  const glow = Math.max(0, 1.0 - Math.abs(rd)*0.3);
  const bright = pulse * edge * (0.9 + glow*0.1);
  return [
    Math.min(255, (c0[0]+(c1[0]-c0[0])*f)*bright)|0,
    Math.min(255, (c0[1]+(c1[1]-c0[1])*f)*bright)|0,
    Math.min(255, (c0[2]+(c1[2]-c0[2])*f)*bright)|0
  ];
}
